<form class="filters" method="get"><label><?= e(__('fields.status')) ?><select name="status"><?php foreach (['' => 'All current records', 'active' => 'Active processing', 'not_started' => 'Not started', 'submitted' => 'Submitted', 'processing' => 'Processing', 'completed' => 'Completed'] as $value => $label): ?><option value="<?= e($value) ?>" <?= selected($status, $value) ?>><?= e($label) ?></option><?php endforeach; ?></select></label><button class="btn btn-ghost" type="submit"><?= e(__('actions.filter')) ?></button></form>
<?php if ($rows === []): ?><p class="empty"><?= e(__('empty.results')) ?></p><?php endif; ?>
<?php foreach ($rows as $row): ?><p><a href="<?= e(url('/admin/cases/' . $row['case_id'])) ?>"><?= e($row['number']) ?></a> <?= e($row['customer_name']) ?> · <?= e($row['status']) ?></p><?php endforeach; ?>
